#include <string.h>
#include <wchar.h>
void memory(char *dst, char *src, size_t offset, size_t count, size_t size,
            wchar_t *wide_dst, const wchar_t *wide_src) {
    memcpy(dst + offset, src++, count * size); /* preserve exactly once */
    memmove(dst, src, count);
    wmemcpy(wide_dst, wide_src, count);
    int ordering = strcmp(dst, src);
    (void)ordering;
}

