#include <stddef.h>
#include <stdarg.h>
#include <stdlib.h>
struct Pair { int first; long second; };
typedef unsigned long Count;
static void cleanup(void) { }
static int compare(const void *a, const void *b) {
    return (*(const int *)a > *(const int *)b) - (*(const int *)a < *(const int *)b);
}
void layout(int *array, size_t count, int marker, ...) {
    size_t offset = offsetof(struct Pair, second);
    va_list args;
    va_start(args, marker);
    Count item = va_arg(args, Count);
    va_end(args);
    qsort(array, count, sizeof *array, compare);
    atexit(cleanup);
    (void)offset; (void)item;
}

