#include <math.h>
#include <assert.h>
#include <setjmp.h>
#define WRAP(value) (value)
static jmp_buf environment;
void macros(double x) {
    double outer = WRAP(pow(x, 2));
    double inner = sqrt(WRAP(pow(x, 2)));
    assert(pow(x, 2) >= 0);
    if (setjmp(environment) == 0) longjmp(environment, 1);
    (void)outer; (void)inner;
}

